import {currentEmailTemplateRepository} from '../../backend/email-templates.mjs';
import {emailReviewRequest,isolatedPreview} from '../orders/email-review.mjs';
const fields=['subject','heading','body'];
export function publishConfirmation(row,{document=globalThis.document}={}){
 return new Promise(resolve=>{const previous=document.activeElement,d=document.createElement('dialog');d.className='template-publish';const h=document.createElement('h2');h.textContent='Publish email template';h.id='publish-template-title';d.setAttribute('aria-labelledby',h.id);const p=document.createElement('p');const changed=fields.filter(k=>row.draft[k]!==row.published.content[k]);p.textContent=`${row.template_key}: version ${row.published.version} → ${row.published.version+1}. Changed fields: ${changed.join(', ')||'none'}. This affects future uses and invalidates older previews. Publishing sends no email.`;
 const actions=document.createElement('div');actions.className='template-actions';for(const [label,value] of [['Cancel',false],['Publish',true]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.addEventListener('click',()=>finish(value));actions.append(b);}function finish(v){d.close();d.remove();previous?.focus();resolve(v);}d.addEventListener('cancel',e=>{e.preventDefault();finish(false);});d.append(h,p,actions);document.body.append(d);d.showModal();actions.firstChild.focus();});
}
export async function mountEmailTemplateStudio({document=globalThis.document,repository=currentEmailTemplateRepository(),preview=emailReviewRequest,confirm=message=>document.defaultView.confirm(message),publication=publishConfirmation}={}){
 const $=s=>document.querySelector(s),form=$('#template-form'),status=$('#template-status');let rows=[],selected=null,dirty=false,busy=false,activeField=form.elements.body;
 const content=()=>Object.fromEntries(fields.map(k=>[k,form.elements[k].value]));
 const title=key=>(key.startsWith('aftercare:')?'Customer Aftercare':'Dispatch Confirmation')+' · '+(key.endsWith(':EBAY')?'eBay':'Website');
 const node=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
 function clearPreview(){$('#template-html').srcdoc='';$('#template-text').textContent='';$('#preview-subject').textContent='';$('#preview-context').textContent='Preview uses clearly labelled sample data and never sends.';}
 function state(){if(!selected)return;$('#template-state').textContent=`Published and Live: version ${selected.published.version}. Future emails use this version. `+(dirty?'Unsaved changes.':selected.draft?'Saved Draft: unpublished changes.':'No unpublished draft.');$('#draft-publish').disabled=busy||dirty||!selected.draft;$('#draft-discard').disabled=busy||!selected.draft;}
 function choose(row){selected=row;dirty=false;$('#template-editor').hidden=false;$('#editor-title').textContent=title(row.template_key);for(const key of fields)form.elements[key].value=(row.draft||row.published.content)[key];const select=$('#placeholder-select');select.replaceChildren();for(const key of ['first_name','order_number',...(row.template_key.startsWith('dispatched:')?['shipping_service','tracking_reference']:[])]){const o=node('option','{{'+key+'}}');o.value=key;select.append(o);}renderHistory();clearPreview();state();for(const b of $('#template-list').children)b.toggleAttribute('aria-current',b.dataset.key===row.template_key);}
 function renderHistory(){const root=$('#template-history');root.replaceChildren();for(const v of selected.history){const a=node('article'),p=node('p',`Version ${v.version}${v.id===selected.current_version?' · Published and Live':''} · ${new Date(v.published_at).toLocaleString('en-GB')} · Publisher: ${v.published_by||'Initial system seed'}`);a.append(p);for(const [label,action] of [['Preview version',()=>showPreview({versionId:v.id},'Published version '+v.version)],['Restore to Draft',async()=>{if(dirty&&!confirm('Discard unsaved edits and restore this version into a new draft?'))return;await mutate('restore',null,v.id);}]]){const b=node('button',label);b.type='button';b.addEventListener('click',()=>run(action));a.append(b);}root.append(a);}}
 async function load(){const key=selected?.template_key;rows=await repository.list();if(!Array.isArray(rows)||rows.length!==4)throw Error('Expected four published email templates');const list=$('#template-list');list.replaceChildren();for(const row of rows){const b=node('button',`${title(row.template_key)} · v${row.published.version} · ${new Date(row.published.published_at).toLocaleString('en-GB')} · ${row.draft?'Saved Draft':'No draft'}${row.updated_by?' · Editor '+row.updated_by:''}`);b.type='button';b.dataset.key=row.template_key;b.addEventListener('click',()=>{if(busy||dirty&&!confirm('Discard unsaved edits before changing template?'))return;choose(row);});list.append(b);}choose(rows.find(r=>r.template_key===key)||rows[0]);}
 async function mutate(action,value=null,version=null){await repository.mutate(selected.template_key,selected.revision,action,value,version);await load();status.textContent=action==='publish'?'Published and Live. Future uses now use the new version. No email was sent.':action==='save'?'Saved Draft. Live content has not changed.':action==='restore'?'Historical version restored into a new draft. Live content has not changed.':'Draft discarded. Published content is unchanged.';}
 async function showPreview(options={},indicator=dirty?'Unsaved Draft':selected.draft?'Saved Draft':'Published and Live'){
  const data=await preview('template-preview',{key:selected.template_key,...Object.keys(options).length?options:{content:content()},tracking:true});if(typeof data.html!=='string'||typeof data.text!=='string')throw Error('Invalid preview response');$('#template-html').srcdoc=isolatedPreview(data.html);$('#template-text').textContent=data.text;$('#template-text').scrollTop=0;$('#preview-subject').textContent=data.subject;$('#preview-context').textContent=`${data.label} · ${title(data.key)} · ${indicator} · ${data.orderReference}`;status.textContent='Content validated. Preview only; nothing was sent.';
 }
 async function run(action){if(busy)return;busy=true;document.querySelector('#template-editor').setAttribute('aria-busy','true');document.querySelectorAll('.template-layout button,#template-form input,#template-form textarea,#template-form select').forEach(b=>b.disabled=true);try{await action();}catch(error){status.textContent=error.message+(error.code==='40001'?' Your edits remain in the editor. Reload explicitly to review the newer version.':'');}finally{busy=false;$('#template-editor').removeAttribute('aria-busy');document.querySelectorAll('.template-layout button,#template-form input,#template-form textarea,#template-form select').forEach(b=>b.disabled=false);state();}}
 form.addEventListener('submit',e=>e.preventDefault());for(const field of fields){form.elements[field].addEventListener('focus',()=>activeField=form.elements[field]);form.elements[field].addEventListener('input',()=>{dirty=true;clearPreview();state();});}
 $('#placeholder-insert').addEventListener('click',()=>{const placeholder='{{'+$('#placeholder-select').value+'}}',start=activeField.selectionStart??activeField.value.length,end=activeField.selectionEnd??start;activeField.setRangeText(placeholder,start,end,'end');activeField.focus();dirty=true;clearPreview();state();});
 $('#draft-save').addEventListener('click',()=>run(()=>mutate('save',content())));
 $('#draft-preview').addEventListener('click',()=>run(()=>showPreview()));
 $('#draft-discard').addEventListener('click',()=>{if(confirm('Discard the saved draft and any unsaved edits? Published content remains unchanged.'))run(()=>mutate('discard'));});
 $('#draft-publish').addEventListener('click',()=>run(async()=>{if(dirty||!selected.draft)throw Error('Save the draft before publishing');await showPreview();if(await publication(selected,{document}))await mutate('publish');}));
 $('#template-reload').addEventListener('click',()=>{if(!dirty||confirm('Discard unsaved edits and reload templates?'))run(load);});
 for(const format of ['html','text'])$('#preview-'+format).addEventListener('click',()=>{const html=format==='html';$('#template-html').hidden=!html;$('#template-text').hidden=html;$('#preview-html').setAttribute('aria-pressed',String(html));$('#preview-text').setAttribute('aria-pressed',String(!html));});
 document.defaultView.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
 await run(async()=>{await load();status.textContent='Four template variants loaded. Publishing never sends an email.';});return {get selected(){return selected;},get dirty(){return dirty;}};
}
if(typeof document!=='undefined'&&document.querySelector('#template-form'))mountEmailTemplateStudio();
